  addStep();
  playSeq();
  if(!checkInput()) { gameOver(); gameLen=0; delay(1000); }
  delay(500);
}
void addStep() {
  sequence[gameLen] = random(0, 4);
  gameLen++;
}
void playSeq() {
  for(int i=0; i<gameLen; i++) {
    int p = sequence[i];
    digitalWrite(ledPins[p], HIGH);
    tone(buzzerPin, 200 + p*150, 300);
    delay(400);
    digitalWrite(ledPins[p], LOW);
    delay(200);
  }
}
bool checkInput() {
  for(int i=0; i<gameLen; i++) {
    int pressed = -1;
    unsigned long start = millis();
    while(millis() - start < 2000) {
      for(int j=0; j<4; j++) {
        if(digitalRead(btnPins[j]) == LOW) {
          pressed = j;
          digitalWrite(ledPins[j], HIGH);
          tone(buzzerPin, 200 + j*150, 200);
          delay(250);
          digitalWrite(ledPins[j], LOW);
          while(digitalRead(btnPins[j]) == LOW);
          break;
        }
      }
      if(pressed != -1) break;
    }
    if(pressed != sequence[i]) return false;
  }
  return true;
}
void gameOver() {
  for(int i=0; i<3; i++) {
    tone(buzzerPin, 100, 150);
    delay(200);
  }
