int readButton() {
  while(true) {
    for(int i=0; i<4; i++) {
      if(digitalRead(btnPins[i]) == LOW) {
        digitalWrite(ledPins[i], HIGH);
        if(i == 0) tone(buzzerPin, 200);
        else if(i == 1) tone(buzzerPin, 300);
        else if(i == 2) tone(buzzerPin, 400);
        else tone(buzzerPin, 500);

